<div x-show="open" x-cloak @keydown.escape.window="open = false" @click.self="open = false" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4 backdrop-blur-sm">
    <div class="w-full max-w-sm rounded-3xl bg-white p-6 shadow-2xl" @click.stop>
        <div class="flex items-center justify-between"><div><p class="text-xs font-semibold uppercase tracking-wider text-blue-700">Pilih waktu</p><p class="mt-1 text-3xl font-black text-gray-800" x-text="displayValue"></p></div><button type="button" @click="open = false" class="flex h-9 w-9 items-center justify-center rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200"><i class="fas fa-times"></i></button></div>
        <div class="mt-5 flex gap-2 rounded-xl bg-gray-100 p-1"><button type="button" @click="setPeriod('AM')" :class="period === 'AM' ? 'bg-white text-blue-800 shadow-sm' : 'text-gray-500'" class="flex-1 rounded-lg py-2 text-sm font-bold">AM</button><button type="button" @click="setPeriod('PM')" :class="period === 'PM' ? 'bg-white text-blue-800 shadow-sm' : 'text-gray-500'" class="flex-1 rounded-lg py-2 text-sm font-bold">PM</button></div>
        <div class="mx-auto mt-6 flex h-60 w-60 items-center justify-center rounded-full bg-blue-50 ring-8 ring-blue-50/60"><div class="relative h-52 w-52 rounded-full border border-blue-100 bg-white shadow-inner"><div class="absolute left-1/2 top-1/2 z-10 flex h-12 w-12 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-blue-700 text-xs font-black text-white" x-text="mode === 'hour' ? hour12 : String(minute).padStart(2, '0')"></div><template x-for="(item, index) in mode === 'hour' ? hours : minutes" :key="`${mode}-${item}`"><button type="button" @click="mode === 'hour' ? selectHour(item) : selectMinute(item)" :style="clockPosition(index)" :class="(mode === 'hour' && item === hour12) || (mode === 'minute' && item === minute) ? 'bg-blue-700 text-white' : 'text-gray-700 hover:bg-blue-100'" class="absolute -ml-4 -mt-4 flex h-9 w-9 items-center justify-center rounded-full text-xs font-bold transition" x-text="mode === 'hour' ? item : String(item).padStart(2, '0')"></button></template></div></div>
        <p class="mt-5 text-center text-xs text-gray-500" x-text="mode === 'hour' ? 'Pilih jam terlebih dahulu' : 'Pilih menit' "></p>
    </div>
</div>
